css:
[data-bz-section="site-footer"] .bz-section { background: var(--ink); color: rgba(255,255,255,.72) }
[data-bz-section="site-footer"] [data-bz-node="sf-logo"] img { height: 38px; width: auto; display: block; margin-bottom: var(--space-4) }
[data-bz-section="site-footer"] [data-bz-node="sf-about"] p { font-size: var(--text-small); line-height: 1.6; color: rgba(255,255,255,.6); margin-bottom: 18px }
[data-bz-section="site-footer"] [data-bz-node^="sf-col-h"] h3 { font-family: var(--font-body); font-weight: 700; font-size: var(--text-eyebrow); letter-spacing: .08em; text-transform: uppercase; color: #fff; margin: 0 0 var(--space-4) }
[data-bz-section="site-footer"] .bz-menu--vertical { gap: 10px }
[data-bz-section="site-footer"] .bz-navitem > a { color: rgba(255,255,255,.72); font-size: var(--text-small); padding: 0 }
[data-bz-section="site-footer"] .bz-navitem > a:hover { color: #fff }
[data-bz-section="site-footer"] [data-bz-node="sf-bottom"] { border-top: 1px solid rgba(255,255,255,.14); padding-top: var(--space-5); margin-top: var(--space-6) }
[data-bz-section="site-footer"] [data-bz-node="sf-bottom"] p { margin: 0; font-size: var(--text-eyebrow); color: rgba(255,255,255,.5) }
[data-bz-section="site-footer"] [data-bz-node="sf-legal"] { display: flex; align-items: flex-end; justify-content: flex-end; gap: 18px; flex-wrap: wrap }
[data-bz-section="site-footer"] [data-bz-node="sf-legal"] .bz-menu--horizontal { gap: 18px }
[data-bz-section="site-footer"] [data-bz-node="sf-legal"] .bz-navitem > a { font-size: var(--text-eyebrow) }
[data-bz-section="site-footer"] [data-bz-node="sf-built"] img { height: 16px; width: auto; display: block }
[data-bz-section="site-footer"] [data-bz-node="sf-built"] figure,
[data-bz-section="site-footer"] [data-bz-node="sf-built"] p { margin: 0 }
@media (max-width: 900px) {
  [data-bz-section="site-footer"] [data-bz-node="sf-legal"] { justify-content: flex-start }
}
[data-bz-section="site-footer"] .bz-navitem > a { font-family: var(--font-body); font-weight: 500; font-size: 13px }
[data-bz-section="site-footer"] [data-bz-node^="sf-col-h"] h3 { font-size: var(--text-eyebrow) }
